-- Unmounted isolated SQL draft. Root owns migration/composition. Private managed
-- owner only; no direct service table grants, no credential plaintext columns.
CREATE TABLE pactwoven.native_google_bindings(login name,environment text,lane text CHECK(lane IN('auth','worker')),PRIMARY KEY(login,environment,lane));
CREATE TABLE pactwoven.native_google_attempts(environment text,id text,state_hash text,body jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','reserved','completed','failed')),operation_id text,reserved_until timestamptz,PRIMARY KEY(environment,id),UNIQUE(environment,state_hash));
CREATE TABLE pactwoven.native_google_connections(environment text,id text,body jsonb NOT NULL,refresh_operation text,refresh_until timestamptz,PRIMARY KEY(environment,id));
CREATE TABLE pactwoven.native_google_items(environment text,connection_id text,identity_digest text,event_digest text NOT NULL,message jsonb NOT NULL,PRIMARY KEY(environment,connection_id,identity_digest),FOREIGN KEY(environment,connection_id)REFERENCES pactwoven.native_google_connections);
CREATE TABLE pactwoven.native_google_provenance(environment text,id text,connection_id text NOT NULL,body jsonb NOT NULL,PRIMARY KEY(environment,id),FOREIGN KEY(environment,connection_id)REFERENCES pactwoven.native_google_connections);
CREATE TABLE pactwoven.native_google_cursors(environment text,connection_id text,reference text,etag text NOT NULL,updated_at timestamptz NOT NULL,PRIMARY KEY(environment,connection_id,reference),FOREIGN KEY(environment,connection_id)REFERENCES pactwoven.native_google_connections);
CREATE FUNCTION pactwoven.native_google_require(v boolean,code text DEFAULT 'NG004')RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION USING ERRCODE=code,MESSAGE='Private Google boundary denied';END IF;END $$;
CREATE FUNCTION pactwoven.native_google_validate(v jsonb,k text)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM pactwoven.native_google_require(octet_length(v::text)<=262144 AND pactwoven.native_delegation_matches(v,pactwoven.native_google_schema(k)));END $$;
CREATE FUNCTION pactwoven.native_google_lane(env text,lane text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
BEGIN PERFORM set_config('lock_timeout','2000ms',true);
PERFORM 1 FROM pactwoven.native_google_bindings b JOIN pg_roles r ON r.rolname=b.login WHERE b.login=SESSION_USER AND b.environment=env AND b.lane=lane AND NOT(r.rolsuper OR r.rolbypassrls OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication)FOR SHARE OF b;
PERFORM pactwoven.native_google_require(FOUND,'NG001');END $$;
CREATE FUNCTION pactwoven.native_google_bridge(k text,env text,input jsonb)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE answer jsonb;BEGIN PERFORM pactwoven.native_google_require(k IN('session','read','artifact'),'NG010');
IF to_regprocedure('pactwoven.native_google_bridge_'||k||'(text,jsonb)')IS NULL THEN RAISE EXCEPTION USING ERRCODE='NG010',MESSAGE='Protected Google bridge is not installed';END IF;
EXECUTE format('SELECT pactwoven.%I($1,$2)','native_google_bridge_'||k)INTO answer USING env,input;RETURN answer;END $$;
CREATE FUNCTION pactwoven.native_google_session_fresh(s jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE t timestamptz:=clock_timestamp();BEGIN
PERFORM pactwoven.native_google_require(s#>>'{actor,principalKind}'='human' AND(s#>'{actor,roles}'?'owner' OR s#>'{actor,roles}'?'operations') AND(s->>'verifiedAt')::timestamptz<=t AND(s->>'verifiedAt')::timestamptz>t-interval '20 seconds' AND(s->>'expiresAt')::timestamptz>t AND(s#>>'{actor,authenticatedAt}')::timestamptz<=t,'NG008');END $$;
CREATE FUNCTION pactwoven.native_google_session(env text,s jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM pactwoven.native_google_validate(s,'session');PERFORM pactwoven.native_google_require(s#>>'{actor,environment}'=env AND pactwoven.native_google_bridge('session',env,s)=s,'NG001');PERFORM pactwoven.native_google_session_fresh(s);END $$;
CREATE FUNCTION pactwoven.native_google_same_session(a jsonb,b jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM pactwoven.native_google_require(a->>'subject'=b->>'subject' AND a#>>'{actor,actorId}'=b#>>'{actor,actorId}' AND a#>>'{actor,sessionId}'=b#>>'{actor,sessionId}' AND a#>>'{actor,organizationId}'=b#>>'{actor,organizationId}' AND a#>>'{actor,environment}'=b#>>'{actor,environment}' AND a#>>'{actor,authenticatedAt}'=b#>>'{actor,authenticatedAt}','NG001');END $$;
CREATE FUNCTION pactwoven.native_google_create_attempt(env text,a jsonb)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE t timestamptz;old record;BEGIN
PERFORM pactwoven.native_google_lane(env,'auth');PERFORM pactwoven.native_google_validate(a,'attempt');PERFORM pactwoven.native_google_session(env,a->'session');t:=clock_timestamp();
PERFORM pactwoven.native_google_require(a#>>'{binding,environment}'=env AND a#>>'{binding,organizationId}'=a#>>'{session,actor,organizationId}' AND a#>>'{binding,actorId}'=a#>>'{session,actor,actorId}' AND a#>>'{binding,connectionVersion}'='1' AND a#>>'{binding,credentialVersion}'='1' AND(a->>'createdAt')::timestamptz<=t AND(a->>'createdAt')::timestamptz>t-interval '20 seconds' AND(a->>'expiresAt')::timestamptz>t AND(a->>'expiresAt')::timestamptz<=(a->>'createdAt')::timestamptz+interval '5 minutes' AND(a->>'expiresAt')::timestamptz<=(a#>>'{session,expiresAt}')::timestamptz);
INSERT INTO pactwoven.native_google_attempts(environment,id,state_hash,body)VALUES(env,a->>'id',a->>'stateHash',a)ON CONFLICT DO NOTHING;
SELECT * INTO old FROM pactwoven.native_google_attempts WHERE environment=env AND id=a->>'id' FOR UPDATE;PERFORM pactwoven.native_google_require(FOUND AND old.body=a AND old.status='pending','NG003');PERFORM pactwoven.native_google_session_fresh(a->'session');RETURN true;END $$;
CREATE FUNCTION pactwoven.native_google_reserve_attempt(env text,state_hash text,s jsonb,op text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE a record;BEGIN
PERFORM pactwoven.native_google_lane(env,'auth');PERFORM pactwoven.native_google_session(env,s);
SELECT * INTO a FROM pactwoven.native_google_attempts x WHERE x.environment=env AND x.state_hash=state_hash FOR UPDATE;PERFORM pactwoven.native_google_require(FOUND,'NG001');
PERFORM pactwoven.native_google_same_session(a.body->'session',s);PERFORM pactwoven.native_google_session_fresh(s);
PERFORM pactwoven.native_google_require(a.status='pending' AND(a.body->>'expiresAt')::timestamptz>clock_timestamp() AND op~'^[A-Za-z0-9_-]{1,128}$','NG003');
UPDATE pactwoven.native_google_attempts SET status='reserved',operation_id=op,reserved_until=LEAST(clock_timestamp()+interval '30 seconds',(body->>'expiresAt')::timestamptz)WHERE environment=env AND id=a.id;
RETURN a.body;END $$;
CREATE FUNCTION pactwoven.native_google_complete_attempt(env text,id text,s jsonb,op text,c jsonb)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE a record;BEGIN
PERFORM pactwoven.native_google_lane(env,'auth');PERFORM pactwoven.native_google_session(env,s);PERFORM pactwoven.native_google_validate(c,'connection');PERFORM pactwoven.native_google_require(c->'scopes'='["openid","email","https://www.googleapis.com/auth/calendar.events.readonly"]'::jsonb);
SELECT * INTO a FROM pactwoven.native_google_attempts x WHERE x.environment=env AND x.id=id FOR UPDATE;PERFORM pactwoven.native_google_require(FOUND,'NG001');PERFORM pactwoven.native_google_same_session(a.body->'session',s);PERFORM pactwoven.native_google_session_fresh(s);
PERFORM pactwoven.native_google_require(a.status='reserved' AND a.operation_id=op AND a.reserved_until>clock_timestamp(),'NG003');
PERFORM pactwoven.native_google_require(c->'binding'=a.body->'binding' AND c->>'clientId'=a.body->>'clientId' AND c->>'accountEmail'=a.body->>'expectedEmail' AND c->>'status'='connected');
INSERT INTO pactwoven.native_google_connections(environment,id,body)VALUES(env,c#>>'{binding,connectionId}',c);
UPDATE pactwoven.native_google_attempts x SET status='completed'WHERE x.environment=env AND x.id=id;
-- A conflicting connection INSERT can wait after the initial lease check. All
-- effects above roll back if state/lease expiry crosses that wait.
PERFORM pactwoven.native_google_session_fresh(s);PERFORM pactwoven.native_google_require(a.reserved_until>clock_timestamp() AND(a.body->>'expiresAt')::timestamptz>clock_timestamp(),'NG003');RETURN true;END $$;
CREATE FUNCTION pactwoven.native_google_fail_attempt(env text,id text,op text)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
BEGIN PERFORM pactwoven.native_google_lane(env,'auth');UPDATE pactwoven.native_google_attempts x SET status='failed' WHERE x.environment=env AND x.id=id AND operation_id=op AND status='reserved';RETURN true;END $$;
CREATE FUNCTION pactwoven.native_google_revoke(env text,id text,s jsonb,expected bigint)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE c record;BEGIN PERFORM pactwoven.native_google_lane(env,'auth');PERFORM pactwoven.native_google_session(env,s);
SELECT * INTO c FROM pactwoven.native_google_connections x WHERE x.environment=env AND x.id=id FOR UPDATE;PERFORM pactwoven.native_google_session_fresh(s);
PERFORM pactwoven.native_google_require(FOUND AND c.body#>>'{binding,actorId}'=s#>>'{actor,actorId}' AND c.body#>>'{binding,organizationId}'=s#>>'{actor,organizationId}','NG001');
PERFORM pactwoven.native_google_require((c.body#>>'{binding,connectionVersion}')::bigint=expected AND c.body->>'status' IN('connected','refreshing','unavailable'),'NG003');
UPDATE pactwoven.native_google_connections x SET body=jsonb_set(jsonb_set(body,'{status}','"revoked"'),'{binding,connectionVersion}',to_jsonb(expected+1)),refresh_operation=NULL,refresh_until=NULL WHERE x.environment=env AND x.id=id;PERFORM pactwoven.native_google_session_fresh(s);RETURN true;END $$;
-- Connection row first, then current consent/root/authority bridge. Bridges must
-- hold producer/session/membership/root/grant rows through the SQL transaction.
CREATE FUNCTION pactwoven.native_google_read_fresh(r jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE t timestamptz:=clock_timestamp();BEGIN PERFORM pactwoven.native_google_require((r->>'observedAt')::timestamptz<=t AND(r->>'validUntil')::timestamptz>t AND(r->>'validUntil')::timestamptz-(r->>'observedAt')::timestamptz<=interval '20 seconds' AND(r#>>'{request,expiresAt}')::timestamptz>t,'NG008');END $$;
CREATE FUNCTION pactwoven.native_google_read(env text,id text,ref text,refreshing boolean DEFAULT false)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE c record;r jsonb;q jsonb;BEGIN
SELECT * INTO c FROM pactwoven.native_google_connections x WHERE x.environment=env AND x.id=id FOR UPDATE;
PERFORM pactwoven.native_google_require(FOUND AND(c.body->>'status'='connected' OR(refreshing AND c.body->>'status'='refreshing')),'NG001');
r:=pactwoven.native_google_bridge('read',env,jsonb_build_object('connectionId',id,'providerReference',ref));PERFORM pactwoven.native_google_validate(r,'read');q:=r->'request';
PERFORM pactwoven.native_google_require(r->>'providerReference'=ref AND q#>>'{scope,environment}'=env AND q->>'connectionId'=id AND q#>>'{scope,organizationId}'=c.body#>>'{binding,organizationId}' AND q->>'actorId'=c.body#>>'{binding,actorId}' AND q->'connectionVersion'=c.body#>'{binding,connectionVersion}' AND q->>'accountSubject'=c.body->>'accountSubject' AND q#>>'{target,kind}'='calendar_change','NG001');
PERFORM pactwoven.native_google_read_fresh(r);RETURN jsonb_build_object('read',r,'connection',c.body);END $$;
CREATE FUNCTION pactwoven.native_google_resolve_read(env text,id text,ref text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN PERFORM pactwoven.native_google_lane(env,'worker');RETURN pactwoven.native_google_read(env,id,ref);END $$;
CREATE FUNCTION pactwoven.native_google_reserve_refresh(env text,r jsonb,version bigint,op text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE ctx jsonb;c jsonb;BEGIN
PERFORM pactwoven.native_google_lane(env,'worker');PERFORM pactwoven.native_google_validate(r,'read');ctx:=pactwoven.native_google_read(env,r#>>'{request,connectionId}',r->>'providerReference');c:=ctx->'connection';
PERFORM pactwoven.native_google_require(ctx#>'{read,request}'=r->'request' AND(c#>>'{binding,credentialVersion}')::bigint=version AND op~'^[A-Za-z0-9_-]{1,128}$','NG003');
c:=jsonb_set(c,'{status}','"refreshing"');UPDATE pactwoven.native_google_connections x SET body=c,refresh_operation=op,refresh_until=clock_timestamp()+interval '30 seconds' WHERE x.environment=env AND x.id=r#>>'{request,connectionId}';
PERFORM pactwoven.native_google_read_fresh(ctx->'read');RETURN c;END $$;
CREATE FUNCTION pactwoven.native_google_complete_refresh(env text,r jsonb,op text,c jsonb)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE ctx jsonb;old record;BEGIN
PERFORM pactwoven.native_google_lane(env,'worker');PERFORM pactwoven.native_google_validate(r,'read');PERFORM pactwoven.native_google_validate(c,'connection');PERFORM pactwoven.native_google_require(c->'scopes'='["openid","email","https://www.googleapis.com/auth/calendar.events.readonly"]'::jsonb);
ctx:=pactwoven.native_google_read(env,r#>>'{request,connectionId}',r->>'providerReference',true);
SELECT * INTO old FROM pactwoven.native_google_connections x WHERE x.environment=env AND x.id=r#>>'{request,connectionId}';
PERFORM pactwoven.native_google_require(ctx#>'{read,request}'=r->'request' AND old.refresh_operation=op AND old.refresh_until>clock_timestamp() AND old.body->>'status'='refreshing','NG003');
PERFORM pactwoven.native_google_require(c->>'status'='connected' AND((c->'binding')-'credentialVersion')=((old.body->'binding')-'credentialVersion') AND(c#>>'{binding,credentialVersion}')::bigint=(old.body#>>'{binding,credentialVersion}')::bigint+1 AND(c-'binding'-'tokens'-'status')=(old.body-'binding'-'tokens'-'status'));
UPDATE pactwoven.native_google_connections x SET body=c,refresh_operation=NULL,refresh_until=NULL WHERE x.environment=env AND x.id=r#>>'{request,connectionId}';PERFORM pactwoven.native_google_read_fresh(ctx->'read');RETURN true;END $$;
CREATE FUNCTION pactwoven.native_google_fail_refresh(env text,id text,op text)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
BEGIN PERFORM pactwoven.native_google_lane(env,'worker');UPDATE pactwoven.native_google_connections x SET body=jsonb_set(body,'{status}','"unavailable"'),refresh_operation=NULL,refresh_until=NULL WHERE x.environment=env AND x.id=id AND refresh_operation=op AND body->>'status'='refreshing';RETURN true;END $$;
CREATE FUNCTION pactwoven.native_google_retain_observation(env text,r jsonb,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE ctx jsonb;q jsonb;m jsonb;v jsonb;src jsonb;identity text;cursor_key text;old record;cursor_row record;known boolean;BEGIN
PERFORM pactwoven.native_google_lane(env,'worker');PERFORM pactwoven.native_google_validate(r,'read');PERFORM pactwoven.native_google_validate(p,'provenance');
ctx:=pactwoven.native_google_read(env,r#>>'{request,connectionId}',r->>'providerReference');q:=ctx#>'{read,request}';m:=p->'message';v:=p->'verification';src:=m->'source';
PERFORM pactwoven.native_google_require(q=r->'request' AND p->>'providerReference'=r->>'providerReference' AND m->'scope'=q->'scope' AND m->>'connectionId'=q->>'connectionId' AND m->'connectionVersion'=q->'connectionVersion' AND m->>'accountSubject'=q->>'accountSubject' AND src->>'kind'='calendar_change' AND src->>'calendarId'=q#>>'{target,calendarId}' AND src->>'eventId'=q#>>'{target,eventId}' AND src->>'previousEtag'=q#>>'{target,expectedEtag}' AND src->>'etag'<>src->>'previousEtag' AND(m->>'occurredAt')::timestamptz<=clock_timestamp(),'NG001');
PERFORM pactwoven.native_google_require((src->>'change'='deleted' AND m->'content'='null'::jsonb) OR(src->>'change'='updated' AND m->'content'<>'null'::jsonb AND m#>'{content,scope}'=m->'scope'));
IF m->'content'<>'null'::jsonb THEN PERFORM pactwoven.native_google_require(pactwoven.native_google_bridge('artifact',env,jsonb_build_object('read',ctx->'read','provenance',p))=m->'content','NG001');END IF;
identity:=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/incoming-identity/v1','environment',m#>>'{scope,environment}','organizationId',m#>>'{scope,organizationId}','connectionId',m->>'connectionId','accountSubject',m->>'accountSubject','identity',jsonb_build_object('kind','calendar_change','calendarId',src->>'calendarId','eventId',src->>'eventId','etag',src->>'etag')));
PERFORM pactwoven.native_google_require(v->>'identityDigest'=identity AND v->>'messageDigest'=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/incoming-message/v1','message',m)) AND v->>'connectionId'=m->>'connectionId' AND v->'connectionVersion'=m->'connectionVersion' AND v->>'accountSubject'=m->>'accountSubject' AND v->'authenticatedSender'='null'::jsonb,'NG001');
PERFORM pactwoven.native_google_read_fresh(jsonb_build_object('observedAt',v->>'observedAt','validUntil',v->>'validUntil','request',q));
SELECT * INTO old FROM pactwoven.native_google_items x WHERE x.environment=env AND x.connection_id=q->>'connectionId' AND x.identity_digest=identity;known:=FOUND;
IF known THEN PERFORM pactwoven.native_google_require(old.message=m AND old.event_digest=p->>'eventDigest','NG003');END IF;
-- Cursor identity is the actual Calendar target, never a replaceable approved
-- read reference. Retained items supply the high-water mark for pre-upgrade
-- reference-keyed cursors too; old rows remain intact and cannot reset it.
cursor_key:=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/google-calendar-cursor/v1','calendarId',src->>'calendarId','eventId',src->>'eventId'));
SELECT high.etag,high.updated_at INTO cursor_row FROM(
 SELECT x.etag,x.updated_at FROM pactwoven.native_google_cursors x WHERE x.environment=env AND x.connection_id=q->>'connectionId' AND x.reference=cursor_key
 UNION ALL
 SELECT x.message#>>'{source,etag}',(x.message->>'occurredAt')::timestamptz FROM pactwoven.native_google_items x
 WHERE x.environment=env AND x.connection_id=q->>'connectionId' AND x.message#>>'{source,calendarId}'=src->>'calendarId' AND x.message#>>'{source,eventId}'=src->>'eventId'
)high ORDER BY high.updated_at DESC LIMIT 1;
IF FOUND THEN
 PERFORM pactwoven.native_google_require(CASE WHEN known THEN src->>'etag'=cursor_row.etag AND(m->>'occurredAt')::timestamptz=cursor_row.updated_at
 ELSE(m->>'occurredAt')::timestamptz>cursor_row.updated_at AND src->>'etag'<>cursor_row.etag END,'NG003');
END IF;
IF NOT known THEN INSERT INTO pactwoven.native_google_items VALUES(env,q->>'connectionId',identity,p->>'eventDigest',m);END IF;
INSERT INTO pactwoven.native_google_cursors VALUES(env,q->>'connectionId',cursor_key,src->>'etag',(m->>'occurredAt')::timestamptz)
 ON CONFLICT(environment,connection_id,reference)DO UPDATE SET etag=excluded.etag,updated_at=excluded.updated_at;
INSERT INTO pactwoven.native_google_provenance VALUES(env,p->>'provenanceId',q->>'connectionId',p)ON CONFLICT DO NOTHING;
SELECT * INTO old FROM pactwoven.native_google_provenance x WHERE x.environment=env AND x.id=p->>'provenanceId';PERFORM pactwoven.native_google_require(old.body=p,'NG003');
PERFORM pactwoven.native_google_read_fresh(ctx->'read');PERFORM pactwoven.native_google_read_fresh(jsonb_build_object('observedAt',v->>'observedAt','validUntil',v->>'validUntil','request',q));RETURN p;END $$;
-- Read-only recovery of the original callback outcome. Never returns PKCE,
-- encrypted token material or a permission to retry an ambiguous code exchange.
CREATE FUNCTION pactwoven.native_google_recover_attempt(env text,state_hash text,s jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE a record;c record;BEGIN PERFORM pactwoven.native_google_lane(env,'auth');PERFORM pactwoven.native_google_session(env,s);
SELECT * INTO a FROM pactwoven.native_google_attempts x WHERE x.environment=env AND x.state_hash=state_hash FOR SHARE;PERFORM pactwoven.native_google_require(FOUND,'NG001');PERFORM pactwoven.native_google_same_session(a.body->'session',s);PERFORM pactwoven.native_google_session_fresh(s);
IF a.status='completed' THEN SELECT * INTO c FROM pactwoven.native_google_connections x WHERE x.environment=env AND x.id=a.body#>>'{binding,connectionId}' FOR SHARE;PERFORM pactwoven.native_google_require(FOUND,'NG001');PERFORM pactwoven.native_google_session_fresh(s);RETURN jsonb_build_object('status',c.body->>'status','connectionId',c.id);END IF;
RETURN jsonb_build_object('status',a.status,'connectionId',NULL);END $$;
DO $$ DECLARE t record;f record;BEGIN
 FOR t IN SELECT c.oid::regclass relation,c.relname FROM pg_class c WHERE c.relnamespace='pactwoven'::regnamespace AND c.relkind='r' AND (c.relname LIKE 'native_google_%') LOOP
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t.relation);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t.relation);
  EXECUTE format('REVOKE ALL ON TABLE %s FROM PUBLIC',t.relation);
  IF NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=t.relation AND polname='google_production_owner') THEN EXECUTE format('CREATE POLICY google_production_owner ON %s TO %I USING(true) WITH CHECK(true)',t.relation,CURRENT_USER);END IF;
 END LOOP;
 FOR f IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='pactwoven'::regnamespace AND (proname LIKE 'native_google_%') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);END LOOP;
END $$;
COMMIT;
